    name: "coinflip_do",
    description: "Flip a coin. Returns 'heads' or 'tails'.",
    parameters: {
      type: "object",
      properties: {},
      required: []
    }
  }
];

export default {
  register(toolbox) {
    toolbox.addTools(toolDefinitions);
  },

  async execute(toolName, params, context) {
